package org.sleepwell.app;
import android.app.Activity;import android.content.Intent;import android.os.*;import android.text.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;
import java.util.*;import java.util.concurrent.*;
/** Global local search opens saved records/settings. Opening it never starts an output. */
public final class SearchActivity extends Activity {
    private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private String query="",error="";private int generation;private boolean loaded;private List<SearchIndex.Entry> index=List.of();private LinearLayout results;private TextView status;private EditText input;
    private final Runnable searchLater=this::search;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);if(saved!=null)query=saved.getString("query","");render();}
    @Override protected void onResume(){super.onResume();load();}
    private void load(){int request=++generation;loaded=false;status.setText("Opening local search…");reader.execute(()->{try{List<SearchIndex.Entry> snapshot=SearchData.read(getApplicationContext());runOnUiThread(()->{if(isDestroyed()||request!=generation)return;index=snapshot;loaded=true;error="";search();});}catch(RuntimeException failed){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;error="Search could not open your saved data.";status.setText(error);results.removeAllViews();Design.button(results,"Try again",true,this::load);});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Search SleepWell",this::finish);Design.space(body,16);input=new EditText(this);input.setSingleLine();input.setTextSize(16*Appearance.scale(this));input.setTypeface(Design.font(this,400));input.setTextColor(Design.INK);input.setHintTextColor(Design.MUTED);input.setHint("Alarms, notes, tags or settings");input.setContentDescription("Search query");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});input.setImeOptions(EditorInfo.IME_ACTION_SEARCH);input.setBackground(Design.shape(this,Design.SOFT,14));Design.pad(input,14,12);input.setText(query);body.addView(input,new LinearLayout.LayoutParams(-1,Design.dp(this,56)));input.setOnEditorActionListener((v,action,event)->{if(action!=EditorInfo.IME_ACTION_SEARCH)return false;search();return true;});input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();main.removeCallbacks(searchLater);main.postDelayed(searchLater,180);}public void afterTextChanged(Editable e){}});Design.space(body,12);status=Design.text(body,"",13,400,Design.MUTED);Design.space(body,12);results=Design.col(this);body.addView(results);}
    private void search(){if(!loaded||isDestroyed())return;int request=++generation;String searched=query;List<SearchIndex.Entry> source=index;reader.execute(()->{List<SearchIndex.Entry> found=SearchIndex.find(source,searched);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;results.removeAllViews();if(SearchIndex.normalize(searched).isEmpty()){status.setText("Search your alarms, sleep records and settings.");return;}status.setText(found.isEmpty()?"No matching results":found.size()+(found.size()==100?" results · first 100 shown":found.size()==1?" result":" results"));for(SearchIndex.Entry entry:found){PlanActivity.detail(results,entry.kind==SearchIndex.Kind.ALARM?"alarm":entry.kind==SearchIndex.Kind.RECORD?"report":"settings",entry.title,entry.subtitle,null,()->open(entry));Design.line(results);}});});}
    private void open(SearchIndex.Entry entry){if(entry.kind==SearchIndex.Kind.SETTING){if(entry.id>=0&&entry.id<SearchData.SETTINGS.length)startActivity(RecordUi.intent(this,SearchData.SETTINGS[(int)entry.id]));return;}if(entry.kind==SearchIndex.Kind.RECORD){startActivity(RecordUi.intent(this,RecordReportActivity.class).putExtra("record",entry.id));return;}int request=++generation;reader.execute(()->{String saved=null;try(Store store=Records.open(getApplicationContext())){Alarm alarm=store.alarm(Math.toIntExact(entry.id));if(alarm!=null)saved=alarm.json().toString();}catch(RuntimeException ignored){}String draft=saved;runOnUiThread(()->{if(isDestroyed()||request!=generation)return;if(draft==null){status.setText("This alarm changed. Refresh the search.");load();}else startActivity(RecordUi.intent(this,AlarmEditorActivity.class).putExtra("alarm",draft));});});}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("query",query);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){generation++;main.removeCallbacksAndMessages(null);reader.shutdownNow();super.onDestroy();}
    boolean awaitReaders(long millis)throws InterruptedException{return reader.awaitTermination(millis,TimeUnit.MILLISECONDS);}
}
